INSERT INTO experience (id, company, role, period, duration, description, highlight, tech, sort_order) VALUES
(1, 'Innovix Solutions', 'Junior Frontend Developer', '3 months', '3 months', 'After my internship, I moved into the Junior Frontend Developer role at Innovix Solutions, taking on more ownership of the frontend work on the Core Insurance System and the Customer Care Admin Panel. I developed and maintained responsive, user-friendly interfaces using React and TypeScript, building reusable components so screens stayed consistent across both products. I integrated REST APIs to retrieve, submit, and manage application data, handling loading and error states so the interfaces stayed reliable. I worked closely with the team to keep the interfaces clean, maintainable, and easy to build on.', 'More ownership of the frontend across both admin products', 'React, TypeScript, REST APIs, Tailwind CSS', 1),
(2, 'Innovix Solutions', 'Frontend Developer Intern', '3 months', '3 months', 'I joined Innovix Solutions as a Frontend Developer Intern, learning the team''s codebase by building real screens for the Core Insurance System and the Customer Care Admin Panel. I developed responsive, user-friendly interfaces using React and TypeScript, and integrated REST APIs to retrieve, submit, and manage application data. Working with the team, I practised writing clean, maintainable code and turning designs into working interfaces that people could actually use.', 'First real product work — responsive interfaces for insurance and customer care', 'React, TypeScript, REST APIs', 2);
INSERT INTO projects (id, title, role, period, description, highlight, tech, demo_url, source_url, sort_order) VALUES
(1, 'Core Insurance System', 'Frontend Developer', 'Innovix Solutions', 'A Core Insurance System for managing insurance applications and data. I developed and maintained responsive, user-friendly interfaces using React and TypeScript, building reusable components for the system’s screens and workflows. I integrated REST APIs to retrieve, submit, and manage application data, so the information on screen always reflected what the system held.', 'Insurance workflows rebuilt as responsive, easy-to-use screens', 'React, TypeScript, REST APIs, Tailwind CSS', NULL, NULL, 1),
(2, 'Customer Care Admin Panel', 'Frontend Developer', 'Innovix Solutions', 'An admin panel for customer care teams to look up, update, and manage customer information. I developed and maintained a responsive, user-friendly interface using React and TypeScript, with reusable components for lists, forms, and detail screens. I integrated REST APIs to retrieve, submit, and manage application data, and used React Hook Form with Zod for validated forms.', 'Admin workflows for support teams, with validated forms and API-driven data', 'React, TypeScript, REST APIs, React Hook Form, Zod', NULL, NULL, 2),
(3, 'Personal Portfolio', 'Frontend Developer', 'Personal Project', 'This portfolio website — my own site, built to show my work and skills. I built it with Next.js 15, React, and TypeScript, styled with Tailwind CSS and animated with Framer Motion. The content lives in a Neon PostgreSQL database and is fetched live on every visit, the source is on GitHub, and the site is deployed on Vercel.', 'Live data from Neon PostgreSQL, deployed on Vercel', 'Next.js, React, TypeScript, Tailwind CSS, Framer Motion, Neon PostgreSQL', NULL, 'https://github.com/Zenn257920/zenn-portfolio', 3),
(4, 'Smart Ride — Shared Ride App', 'Frontend Developer', 'Innovix SharedRide Myanmar', 'A production carpool app built with Next.js 15, React, TypeScript and Tailwind CSS — 11 pages and 27 API routes. Riders search and book rides, drivers offer rides and manage them from a dashboard, and passengers can request a shared ride. A real server database (Neon PostgreSQL + Drizzle) keeps riders and drivers in sync across phones, with Better Auth login, separate passenger and driver accounts, a wallet with manual top-up and cash, and Leaflet maps.', 'Fair-split pricing: shared fares split by route segment, driver paid only when a ride is accepted', 'Next.js, React, TypeScript, Tailwind CSS, Neon PostgreSQL, Drizzle, Better Auth, Leaflet', 'https://smart-ride-app-eight.vercel.app/', 'https://github.com/Zenn257920/smart-ride-app', 4),
(5, 'Expense Tracker', 'Frontend Developer', 'Personal Project', 'A personal finance dashboard for tracking income and expenses by category, with a dashboard, six-month chart, transaction search and filters, categories, loans and CSV export. The standout feature is Burmese voice entry: speak in Burmese or English, and a local parser understands Burmese digits, number words like five thousand and one lakh, categories and dates, then fills in the amount, type, category and date for review before saving. Data lives in Neon PostgreSQL via Drizzle, with Better Auth login and Yangon-time dates.', 'Burmese voice transactions — speak and the form fills itself, no typing', 'Next.js, React, TypeScript, Tailwind CSS, Neon PostgreSQL, Drizzle, Better Auth', 'https://expense-tracker.vercel.app/', 'https://github.com/Zenn257920/expense-tracker', 5),
(6, 'We Talk — Real-time Chat App', 'Frontend Developer', 'Personal Project', 'A real-time chat app for friends. Sign up with email and password or Google, add friends, then chat 1:1 or in groups — no public rooms, friends only. Messages, photos, voice messages, reactions, replies and edits sync live, with typing indicators, presence, push notifications that work when the app is closed, and a Together counter on private chats. Built as an Android app with Capacitor from the same Next.js codebase, backed by Neon PostgreSQL.', 'Friends-only 1:1 and group chat with live sync and closed-app push notifications', 'Next.js, React, TypeScript, Tailwind CSS, Neon PostgreSQL, Drizzle, Better Auth, Firebase FCM, Capacitor', 'https://couple-chat-umber.vercel.app/', 'https://github.com/Zenn257920/couple-chat', 6);
INSERT INTO services (id, title, description, sort_order) VALUES
(1, 'Frontend Development', 'I build complete frontends with React, Next.js, and TypeScript — components, pages, and routing — so the product works end to end, not just on one screen. The code is written to be clean and maintainable, so it stays easy to change and build on later.', 1),
(2, 'Responsive UI Development', 'I build interfaces that hold up on phones, tablets, and desktops, using Tailwind CSS, Bootstrap, Material UI, DaisyUI, and Framer Motion. Motion is used to guide attention, and layouts are checked at real sizes so nothing breaks on a small screen.', 2),
(3, 'API Integration', 'I connect the frontend to real data with REST APIs and Axios — fetching lists, submitting forms, and handling loading and error states. The UI stays in sync with what the server returns, so what people see is always up to date.', 3),
(4, 'Forms & State Management', 'I build forms with React Hook Form and Zod that validate as you type, with clear errors and no lost input. Shared state is managed with Redux Toolkit and Context API, so different screens stay consistent with each other.', 4),
(5, 'Reusable Components & Design Systems', 'I build reusable components and consistent interface patterns, so screens share the same building blocks instead of being rebuilt from scratch. That keeps products consistent, easier to maintain, and faster to extend with new features.', 5);
